69: /* This is called at different times for encoding and decoding.  The
70:  * encoder calls it immediately, the decoder delays until the
71:  * application header is received.  */
72: static int main_set_source(xd3_stream *stream, xd3_cmd cmd, main_file *sfile,
73:                            xd3_source *source) {
74:   int ret = 0;
75:   usize_t i;
76:   xoff_t source_size = 0;
77:   usize_t blksize;
78: 
79:   XD3_ASSERT(lru == NULL);
80:   XD3_ASSERT(stream->src == NULL);
81:   XD3_ASSERT(option_srcwinsz >= XD3_MINSRCWINSZ);
82: 
83:   /* TODO: this code needs refactoring into FIFO, LRU, FAKE.  Yuck!
84:    * This is simplified from 3.0z which had issues with sizing the
85:    * source buffer memory allocation and the source blocksize. */
86: 
87:   /* LRU-specific */
88:   main_blklru_list_init(&lru_list);
89: 
90:   if (allow_fake_source) {
91:     /* TODO: refactor
92:      * TOOLS/recode-specific: Check "allow_fake_source" mode looks
93:      * broken now. */
94:     sfile->mode = XO_READ;
95:     sfile->realname = sfile->filename;
96:     sfile->nread = 0;
97:   } else {
98:     /* Either a regular file (possibly compressed) or a FIFO
99:      * (possibly compressed). */
100:     if ((ret = main_file_open(sfile, sfile->filename, XO_READ))) {
101:       return ret;
102:     }
103: 
104:     /* If the file is regular we know it's size.  If the file turns
105:      * out to be externally compressed, size_known may change. */
106:     sfile->size_known = (main_file_stat(sfile, &source_size) == 0);
107:   }
108: 
109:   /* Clamp the source window to the known source size.  A large -B on a small
110:    * source would otherwise reserve the full (rounded-up) window up front --
111:    * e.g. an 8 GiB buffer for a 100 KB file -- wasting memory and risking
112:    * out-of-memory failures.  Only shrink, never below XD3_MINSRCWINSZ, and only
113:    * when the size is known; non-seekable sources keep the full window because
114:    * they need it.  For an externally compressed source the known size is the
115:    * compressed length, so the window is bounded by that length; this stays
116:    * correct because the logical content is read through the block cache. */
117:   if (sfile->size_known && source_size < option_srcwinsz) {
118:     option_srcwinsz = xd3_max((xoff_t)XD3_MINSRCWINSZ, source_size);
119:   }
120: 
121:   /* Note: The API requires a power-of-two blocksize and srcwinsz
122:    * (-B).  The logic here will use a single block if the entire file
123:    * is known to fit into srcwinsz. */
124:   option_srcwinsz = xd3_xoff_roundup(option_srcwinsz);
125: 
126:   /* Though called "lru", it is not LRU-specific.  We always allocate
127:    * a maximum number of source block buffers.  If the entire file
128:    * fits into srcwinsz, this buffer will stay as the only
129:    * (lru_size==1) source block.  Otherwise, we know that at least
130:    * option_srcwinsz bytes are available.  Split the source window
131:    * into buffers. */
132:   if ((lru = (main_blklru *)main_malloc(MAX_LRU_SIZE * sizeof(main_blklru))) ==
133:       NULL) {
134:     ret = ENOMEM;
135:     return ret;
136:   }
137: 
138:   memset(lru, 0, sizeof(lru[0]) * MAX_LRU_SIZE);
139: 
140:   /* Allocate the entire buffer. */
141:   if ((lru[0].blk = (uint8_t *)main_bufalloc(option_srcwinsz)) == NULL) {
142:     ret = ENOMEM;
143:     return ret;
144:   }
145: 
146:   /* Main calls main_getblk_func() once before xd3_set_source().  This
147:    * is the point at which external decompression may begin.  Set the
148:    * system for a single block. */
149:   lru_size = 1;
150:   lru[0].blkno = XD3_INVALID_OFFSET;
151:   blksize = option_srcwinsz;
152:   main_blklru_list_push_back(&lru_list, &lru[0]);
153:   XD3_ASSERT(blksize != 0);
154: 
155:   /* Initialize xd3_source. */
156:   source->blksize = blksize;
157:   source->name = sfile->filename;
158:   source->ioh = sfile;
159:   source->curblkno = XD3_INVALID_OFFSET;
160:   source->curblk = NULL;
161:   source->max_winsize = option_srcwinsz;
162: 
163:   if ((ret = main_getblk_func(stream, source, 0)) != 0) {
164:     XPR(NT "error reading source: %s: %s\n", sfile->filename,
165:         xd3_mainerror(ret));
166:     return ret;
167:   }
168: 
169:   source->onblk = lru[0].size; /* xd3 sets onblk */
170: 
171:   /* If the file is smaller than a block, size is known. */
172:   if (!sfile->size_known && source->onblk < blksize) {
173:     source_size = source->onblk;
174:     source->onlastblk = source_size;
175:     sfile->size_known = 1;
176:   }
177: 
178:   /* If the size is not known or is greater than the buffer size, we
179:    * split the buffer across MAX_LRU_SIZE blocks (already allocated in
180:    * "lru"). */
181:   if (!sfile->size_known || source_size > option_srcwinsz) {
182:     /* Modify block 0, change blocksize. */
183:     blksize = option_srcwinsz / MAX_LRU_SIZE;
184:     source->blksize = blksize;
185:     source->onblk = blksize;
186:     source->onlastblk = blksize;
187:     source->max_blkno = MAX_LRU_SIZE - 1;
188: 
189:     lru[0].size = blksize;
190:     lru_size = MAX_LRU_SIZE;
191: 
192:     /* Setup rest of blocks. */
193:     for (i = 1; i < lru_size; i += 1) {
194:       lru[i].blk = lru[0].blk + (blksize * i);
195:       lru[i].blkno = i;
196:       lru[i].size = blksize;
197:       main_blklru_list_push_back(&lru_list, &lru[i]);
198:     }
199:   }
200: 
201:   if (!sfile->size_known) {
202:     /* If the size is not know, we must use FIFO discipline. */
203:     do_src_fifo = 1;
204:   }
205: 
206:   /* Call the appropriate set_source method, handle errors, print
207:    * verbose message, etc. */
208:   if (sfile->size_known) {
209:     ret = xd3_set_source_and_size(stream, source, source_size);
210:   } else {
211:     ret = xd3_set_source(stream, source);
212:   }
213: 
214:   if (ret) {
215:     XPR(NT XD3_LIB_ERRMSG(stream, ret));
216:     return ret;
217:   }
218: 
219:   XD3_ASSERT(stream->src == source);
220:   XD3_ASSERT(source->blksize == blksize);
221: 
222:   if (option_verbose) {
223:     static shortbuf srcszbuf;
224:     static shortbuf srccntbuf;
225:     static shortbuf winszbuf;
226:     static shortbuf blkszbuf;
227:     static shortbuf nbufs;
228: 
229:     if (sfile->size_known) {
230:       short_sprintf(srcszbuf, "source size %s [%" XD3_Q "u]",
231:                     main_format_bcnt(source_size, &srccntbuf), source_size);
232:     } else {
233:       short_sprintf(srcszbuf, "%s", "source size unknown");
234:     }
235: 
236:     nbufs.buf[0] = 0;
237: 
238:     if (option_verbose > 1) {
239:       short_sprintf(nbufs, " #bufs %" XD3_W "u", lru_size);
240:     }
241: 
242:     XPR(NT "source %s %s blksize %s window %s%s%s\n", sfile->filename,
243:         srcszbuf.buf, main_format_bcnt(blksize, &blkszbuf),
244:         main_format_bcnt(option_srcwinsz, &winszbuf), nbufs.buf,
245:         do_src_fifo ? " (FIFO)" : "");
246:   }
247: 
248:   return 0;
249: }
