251: static int main_getblk_lru(xd3_source *source, xoff_t blkno,
252:                            main_blklru **blrup, int *is_new) {
253:   main_blklru *blru = NULL;
254:   usize_t i;
255: 
256:   (*is_new) = 0;
257: 
258:   if (do_src_fifo) {
259:     /* Direct lookup assumes sequential scan w/o skipping blocks. */
260:     int idx = (int)(blkno % lru_size);
261:     blru = &lru[idx];
262:     if (blru->blkno == blkno) {
263:       (*blrup) = blru;
264:       return 0;
265:     }
266:     /* No going backwards in a sequential scan. */
267:     if (blru->blkno != XD3_INVALID_OFFSET && blru->blkno > blkno) {
268:       return XD3_TOOFARBACK;
269:     }
270:   } else {
271:     /* Sequential search through LRU. */
272:     for (i = 0; i < lru_size; i += 1) {
273:       blru = &lru[i];
274:       if (blru->blkno == blkno) {
275:         main_blklru_list_remove(blru);
276:         main_blklru_list_push_back(&lru_list, blru);
277:         (*blrup) = blru;
278:         IF_DEBUG1(DP(RINT "[getblk_lru] HIT blkno = %" XD3_Q
279:                           "u lru_size=%" XD3_W "u\n",
280:                      blkno, lru_size));
281:         return 0;
282:       }
283:     }
284:     IF_DEBUG1(DP(RINT "[getblk_lru] MISS blkno = %" XD3_Q "u lru_size=%" XD3_W
285:                       "u\n",
286:                  blkno, lru_size));
287:   }
288: 
289:   if (do_src_fifo) {
290:     int idx = (int)(blkno % lru_size);
291:     blru = &lru[idx];
292:   } else {
293:     XD3_ASSERT(!main_blklru_list_empty(&lru_list));
294:     blru = main_blklru_list_pop_front(&lru_list);
295:     main_blklru_list_push_back(&lru_list, blru);
296:   }
297: 
298:   lru_filled += 1;
299:   (*is_new) = 1;
300:   (*blrup) = blru;
301:   blru->blkno = XD3_INVALID_OFFSET;
302:   return 0;
303: }
