305: static int main_read_seek_source(xd3_stream *stream, xd3_source *source,
306:                                  xoff_t blkno) {
307:   xoff_t pos = blkno * source->blksize;
308:   main_file *sfile = (main_file *)source->ioh;
309:   main_blklru *blru;
310:   int is_new;
311:   size_t nread = 0;
312:   int ret = 0;
313: 
314:   if (!sfile->seek_failed) {
315:     ret = main_file_seek(sfile, pos);
316: 
317:     if (ret == 0) {
318:       sfile->source_position = pos;
319:     }
320:   }
321: 
322:   if (sfile->seek_failed || ret != 0) {
323:     /* For an unseekable file (or other seek error, does it
324:      * matter?) */
325:     if (sfile->source_position > pos) {
326:       /* Could assert !IS_ENCODE(), this shouldn't happen
327:        * because of do_src_fifo during encode. */
328:       if (!option_quiet) {
329:         XPR(NT "source can't seek backwards; requested block offset "
330:                "%" XD3_Q "u source position is %" XD3_Q "u\n",
331:             pos, sfile->source_position);
332:       }
333: 
334:       sfile->seek_failed = 1;
335:       stream->msg = "non-seekable source: "
336:                     "copy is too far back (try raising -B)";
337:       return XD3_TOOFARBACK;
338:     }
339: 
340:     /* There's a chance here, that an genuine lseek error will cause
341:      * xdelta3 to shift into non-seekable mode, entering a degraded
342:      * condition.  */
343:     if (!sfile->seek_failed && option_verbose) {
344:       XPR(NT "source can't seek, will use FIFO for %s\n", sfile->filename);
345: 
346:       if (option_verbose > 1) {
347:         XPR(NT "seek error at offset %" XD3_Q "u: %s\n", pos,
348:             xd3_mainerror(ret));
349:       }
350:     }
351: 
352:     sfile->seek_failed = 1;
353: 
354:     if (option_verbose > 1 && pos != sfile->source_position) {
355:       XPR(NT "non-seekable source skipping %" XD3_Q "u bytes @ %" XD3_Q "u\n",
356:           pos - sfile->source_position, sfile->source_position);
357:     }
358: 
359:     while (sfile->source_position < pos) {
360:       xoff_t skip_blkno;
361:       usize_t skip_offset;
362: 
363:       xd3_blksize_div(sfile->source_position, source, &skip_blkno,
364:                       &skip_offset);
365: 
366:       /* Read past unused data */
367:       XD3_ASSERT(pos - sfile->source_position >= source->blksize);
